// 新代理批准前缀不可在缺模块时回落原首长自签；五kind与四命令逐一限定。
#include "political_governance_agency_profile.hpp"
#include "resident/domains/politics/governance_agency_intents/political_governance_agency_intents.hpp"
#include "hanmo/resident/command_contract.hpp"
#include "resident/domains/politics/politics_governance_profile.hpp"
#include "resident/domains/organization/organization_office_history.hpp"
namespace hanmo::resident {
bool is_political_governance_agency_fact_kind(const StableId& kind){return kind=="political_governance_agency_offered"||kind=="political_governance_agency_accepted"||kind=="political_governance_agency_declined"||kind=="political_governance_agency_revoked"||kind=="political_governance_agency_issued";}
Outcome<Integer> political_governance_agency_selected_version(const std::vector<std::pair<StableId,StableId>>& modules){Integer found=0,version=0,intents=0;for(const auto& m:modules){if(m.first==political_governance_agency_domain){if((m.second!="1"&&m.second!="2")||++found!=1)return {false,0,common_failure("PoliticalGovernanceAgencyModuleMismatch").error};version=m.second=="1"?1:2;}if(m.first==political_governance_agency_intents_module){if(m.second!="1"||++intents!=1)return {false,0,common_failure("GovernanceAgencyIntentVersionPairRequired").error};}}if((version==2)!=(intents==1))return {false,0,common_failure("GovernanceAgencyIntentVersionPairRequired").error};if(!found)return {true,0,{}};for(const auto* dependency:{"politics","politics_governance","governance_tasks","public_relief","family_life"}){Integer count=0;for(const auto& m:modules)if(m.first==dependency){if(m.second!="1"||++count!=1)return {false,0,common_failure("PoliticalGovernanceAgencyDependencyMismatch",dependency).error};}if(count!=1)return {false,0,common_failure("PoliticalGovernanceAgencyDependenciesRequired",dependency).error};}return {true,version,{}};}
// 原治理/赈济pair先原严格准入，只有额外显式版本与能力才有本段。
Outcome<std::optional<PoliticalGovernanceAgencyCatalog>> decode_political_governance_agency_profile(const BoundaryValue& scenario,const std::vector<StableId>& caps){const auto* dynamic=scenario.find("dynamic_world");const auto* group=dynamic?dynamic->find(political_governance_agency_domain):nullptr;auto intents=decode_political_governance_agency_intent_profile(scenario,caps);if(!intents.ok)return {false,{},intents.error};if(!group)return {true,std::nullopt,{}};try{if(!read_politics_governance_profile(*dynamic)||!scenario.find("family_life"))return {false,{},common_failure("PoliticalGovernanceAgencyDependenciesRequired").error};auto decoded=decode_political_governance_agency_catalog(*group);if(!decoded.ok)return {false,{},decoded.error};const auto version=decoded.value.version;const StableId cap=version==1?"political_governance_agencies_v1":"political_governance_agencies_v2";if(std::find(caps.begin(),caps.end(),cap)==caps.end())return {false,{},common_failure("PoliticalGovernanceAgencyCapabilityRequired").error};if((version==2)!=intents.value.has_value())return {false,{},common_failure("GovernanceAgencyIntentVersionPairRequired").error};return {true,std::move(decoded.value),{}};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
Status validate_political_governance_agency_layout(const CommonStore& common,const std::vector<std::pair<StableId,StableId>>& modules,const PoliticalGovernanceAgencyState* state){auto selected=political_governance_agency_selected_version(modules);if(!selected.ok)return {false,{},selected.error};if(bool(state)!=(selected.value!=0)||(state&&(state->version!=selected.value||(state->version==1&&!state->authored_origins.empty()))))return common_failure("PoliticalGovernanceAgencyProfileMismatch");if(!state){for(const auto& row:common.state().facts.rows())if(row.second.domain==political_governance_agency_domain||is_political_governance_agency_fact_kind(row.second.kind)||organization_instance_sequence(row.first,"politics_governance_agency_authority"))return common_failure("PoliticalGovernanceAgencyProfileRequired",row.first);for(const auto& h:common.state().history)if(is_political_governance_agency_command(h.kind))return common_failure("PoliticalGovernanceAgencyProfileRequired",h.result_id);for(const auto& row:common.state().results.rows())if(row.second&&is_political_governance_agency_command(row.second->kind))return common_failure("PoliticalGovernanceAgencyProfileRequired",row.first);}return common_success();}
// 仅本段五头可借此注册；新独占Authority仍必须走原治理账的完整验证。
Status validate_political_governance_agency_fact_header(const CommonStore& common,const PoliticalGovernanceAgencyState& state,const FactRecord& h){if((state.version!=1&&state.version!=2)||h.domain!=political_governance_agency_domain||!political_governance_agency_fact_sequence(common,h.id,h.kind))return common_failure("PoliticalGovernanceAgencyFactMismatch",h.id);if(Integer(bool(state.offers.find(h.id)))+Integer(bool(state.answers.find(h.id)))+Integer(bool(state.revocations.find(h.id)))+Integer(bool(state.issues.find(h.id)))!=1)return common_failure("PoliticalGovernanceAgencyFactMismatch",h.id);const StableId* id=nullptr;if(h.kind=="political_governance_agency_offered"){const auto* p=state.offers.find(h.id);if(p)id=&p->id;}else if(h.kind=="political_governance_agency_accepted"||h.kind=="political_governance_agency_declined"){const auto* p=state.answers.find(h.id);if(p&&p->accept==(h.kind=="political_governance_agency_accepted"))id=&p->id;}else if(h.kind=="political_governance_agency_revoked"){const auto* p=state.revocations.find(h.id);if(p)id=&p->id;}else if(h.kind=="political_governance_agency_issued"){const auto* p=state.issues.find(h.id);if(p)id=&p->id;}return id&&*id==h.id?common_success():common_failure("PoliticalGovernanceAgencyFactMismatch",h.id);}
// 保留完整旧PoliticsEffects布局，但旧命令不能承载本段独占来源。
bool political_governance_agency_effect_uses_sources(const PoliticsEffects& e){for(const auto& id:e.fact_ids)if(id.rfind("political_governance_agency_",0)==0||id.rfind("politics_governance_agency_authority:",0)==0)return true;for(const auto& id:e.receipt_ids)if(id.rfind("political_governance_agency_",0)==0||id.rfind("politics_governance_agency_authority:",0)==0)return true;return e.appointment_id.rfind("political_governance_agency_",0)==0||e.appointment_id.rfind("politics_governance_agency_authority:",0)==0;}
// 代理签发回原治理批准ID，其余命令只有本次业务fact；任何旧Office receipt都不匹配。
bool valid_political_governance_agency_effect(const StableId& kind,const PoliticsEffects& e){if(!e.appointment_id.empty()||e.fact_ids.size()!=1)return false;StableId prefix;if(kind==political_governance_agency_offer_command)prefix="political_governance_agency_offer";else if(kind==political_governance_agency_answer_command)prefix="political_governance_agency_answer";else if(kind==political_governance_agency_revoke_command)prefix="political_governance_agency_revocation";else if(kind==political_governance_agency_issue_command)prefix="political_governance_agency_issue";else return false;if(!organization_instance_sequence(e.fact_ids.front(),prefix))return false;if(kind!=political_governance_agency_issue_command)return e.receipt_ids.empty();return e.receipt_ids.size()==1&&organization_instance_sequence(e.receipt_ids.front(),"politics_governance_agency_authority").has_value();}
}
